tate = Get-Content -LiteralPath $statePath -Raw | ConvertFrom-Json if ($null -eq $state) { return $false } if ($state.PSObject.Properties.Name -notcontains "capability_checked") { return $false } return ($state.capability_checked -eq $true) } catch { # fail-open: 状态读取异常不应卡死 Hook return $true }}function Write-DenyCompat { param( [Parameter(Mandatory = $true)] [string]$Reason, [hashtable]$Details = @{} ) try { if (Get-Command Write-Deny -ErrorAction SilentlyContinue) { Write-Deny -Reason $Reason -Details $Details return } @{ decision = "deny" reason = $Reason details = $Details } | ConvertTo-Json -Depth 10 -Compress } catch { @{ decision = "deny" reason = $Reason details = $Details } | ConvertTo-Json -Depth 10 -Compress }}function Invoke-CapabilityRegistryRequired { param( [Parameter(Mandatory = $true)] [string]$ToolName ) try { $safeTools = @("Read", "Glob", "Grep") if ($safeTools -contains $ToolName) { return $false } if (Test-AndConsumeCapabilityBypass) { return $false } if (Test-CapabilityRegistryChecked) { return $false } Write-DenyCompat ` -Reason "必须先查能力注册表: Grep '关键词' CAPABILITY_REGISTRY.md" ` -Details @{ tool = $ToolName state_path = Get-RunStatePath required_action = "Grep '关键词' CAPABILITY_REGISTRY.md" bypass_once = Get-CapabilityBypassPath policy = "non-read tool requires capability_checked=true" } return $true } catch { # fail-open return $false }}# ---------- block-dangerous.ps1: integration point ----------# 在已有 PreToolUse 主逻辑拿到 $toolName 后，危险检查前加入：# if (Invoke-CapabilityRegistryRequired -ToolName $toolName) { return }# ---------- posttool-recorder.ps1: add helper ----------function Set-RunStateFlagCompat { param( [Parameter(Mandatory = $true)] [string]$Name, [Parameter(Mandatory = $true)] [object]$Value ) try { $statePath = Get-RunStatePath $stateDir = Split-Path -Parent $statePath if (-not (Test-Path -LiteralPath $stateDir)) { New-Item -ItemType Directory -Path $stateDir -Force | Out-Null } $state = $null if (Test-Path -LiteralPath $statePath) { try { $state = Get-Content -LiteralPath $statePath -Raw | ConvertFrom-Json } catch { $state = $null } } if ($null -eq $state) { $state = [pscustomobject]@{} } if ($state.PSObject.Properties.Name -contains $Name) { $state.$Name = $Value } else { $state | Add-Member -NotePropertyName $Name -NotePropertyValue $Value } if ($state.PSObject.Properties.Name -contains "capability_checked_at") { $state.capability_checked_at = (Get-Date).ToString("s") } else { $state | Add-Member -NotePropertyName "capability_checked_at" -NotePropertyValue (Get-Date).ToString("s") } if (Get-Command Save-RunState -ErrorAction SilentlyContinue) { Save-RunState -State $state } else { $state | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $statePath -Encoding UTF8 } } catch { # fail-open return }}function Test-GrepCapabilityRegistry { param( [string]$ToolName, [object]$ToolInput ) try { if ($ToolName -ne "Grep") { return $false } $inputText = "" if ($null -ne $ToolInput) { $inputText = ($ToolInput | ConvertTo-Json -Depth 20 -Compress) } return ($inputText -match "CAPABILITY_REGISTRY(\.md)?") } catch { return $false }}# ---------- posttool-recorder.ps1: integration point ----------# 在已有 PostToolUse 主逻辑解析出 $toolName / $toolInput 后加入：# if (Test-GrepCapabilityRegistry -ToolName $toolName -ToolInput $toolInput) {# Set-RunStateFlagCompat -Name "capability_checked" -Value $true# }
PowerShell# 修改2: D:\Code\.claude\run-state\run-state.lib.ps1# 替换或覆盖现有 Read-RunState / Save-RunState 函数function Read-RunState { $path = Get-RunStatePath $prevPath = "$path.prev" try { if (-not (Test-Path -LiteralPath $path)) { if (Test-Path -LiteralPath $prevPath) { try { Copy-Item -LiteralPath $prevPath -Destination $path -Force -ErrorAction SilentlyContinue return (Get-Content -LiteralPath $path -Raw | ConvertFrom-Json) } catch { return (Get-Content -LiteralPath $prevPath -Raw | ConvertFrom-Json) } } return $null } try { return (Get-Content -LiteralPath $path -Raw | ConvertFrom-Json) } catch { if (Test-Path -LiteralPath $prevPath) { try { Copy-Item -LiteralPath $prevPath -Destination $path -Force -ErrorAction SilentlyContinue return (Get-Content -LiteralPath $path -Raw | ConvertFrom-Json) } catch { try { return (Get-Content -LiteralPath $prevPath -Raw | ConvertFrom-Json) } catch { return $null } } } return $null } } catch { # fail-open return $null }}function Save-RunState { param( [Parameter(Mandatory = $true)] [object]$State ) try { $dir = Get-RunStateDir $path = Get-RunStatePath $tmpPath = "$path.tmp" $prevPath = "$path.prev" if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null } try { $State | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $tmpPath -Encoding UTF8 if (Test-Path -LiteralPath $path) { Copy-Item -LiteralPath $path -Destination $prevPath -Force -ErrorAction SilentlyContinue } Move-Item -LiteralPath $tmpPath -Destination $path -Force return } catch { # fallback: 不阻写，直接写 current.json try { $State | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $path -Encoding UTF8 return } catch { return } } } catch { # fail-open return }}
PowerShell# 修改3: D:\Code\health.ps1# 新增 Hook 完整性校验函数；插入 health 检查项区域，并把 $hookIntegrityCheck 加入汇总function Test-HookIntegrityHealth { Set-StrictMode -Version 2.0 $ErrorActionPreference = "Continue" $root = $env:CLAUDE_PROJECT_DIR if (-not $root) { $root = $PSScriptRoot } $stateDir = Join-Path $root ".claude\run-state" $hashPath = Join-Path $stateDir "hook-hashes.json" $hookFiles = @( (Join-Path $root ".claude\hooks\stop-gate.ps1"), (Join-Path $root ".claude\hooks\posttool-recorder.ps1"), (Join-Path $root ".claude\hooks\block-dangerous.ps1") ) $result = [ordered]@{ name = "hook_integrity" ok = $true level = "OK" first_run = $false baseline_path = $hashPath warnings = @() hooks = @() } try { if (-not (Test-Path -LiteralPath $stateDir)) { New-Item -ItemType Directory -Path $stateDir -Force | Out-Null } $baseline = $null if (Test-Path -LiteralPath $hashPath) { try { $baseline = Get-Content -LiteralPath $hashPath -Raw -Encoding UTF8 | ConvertFrom-Json } catch { $baseline = $null } } if ($null -eq $baseline) { $result.first_run = $true $baseline = [pscustomobject]@{ generated_at = (Get-Date).ToString("s") hooks = [pscustomobject]@{} } } $newHooks = [ordered]@{} foreach ($hookPath in $hookFiles) { $name = Split-Path -Leaf $hookPath $exists = Test-Path -LiteralPath $hookPath $hash = "" if ($exists) { $hash = (Get-FileHash -LiteralPath $hookPath -Algorithm SHA256).Hash } $oldHash = "" if ( $baseline.PSObject.Properties.Name -contains "hooks" -and $null -ne $baseline.hooks -and $baseline.hooks.PSObject.Properties.Name -contains $name ) { $oldHash = [string]$baseline.hooks.$name } $status = "OK" if (-not $exists) { $status = "WARN" $result.level = "WARN" $result.warnings += "hook missing: $name" } elseif (-not $result.first_run -and $oldHash -and $oldHash -ne $hash) { $status = "WARN" $result.level = "WARN" $result.warnings += "hook hash changed: $name" } $result.hooks += [pscustomobject]@{ name = $name path = $hookPath exists = $exists sha256 = $hash previous_sha256 = $oldHash status = $status } if ($exists) { $newHooks[$name] = $hash } } $newBaseline = [pscustomobject]@{ updated_at = (Get-Date).ToString("s") hooks = $newHooks } $newBaseline | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath $hashPath -Encoding UTF8 if ($result.first_run) { $result.level = "OK" $result.ok = $true } Write-Host ("hook_integrity level={0} warnings={1}" -f $result.level, $result.warnings.Count) return [pscustomobject]$result } catch { # health 自身异常按 WARN，不中断整体 $result.level = "WARN" $result.ok = $true $result.warnings += $_.Exception.Message return [pscustomobject]$result }}# 挂载到 health 汇总处：$hookIntegrityCheck = Test-HookIntegrityHealth# 如果 health.ps1 使用 $checks 数组：$checks += $hookIntegrityCheck# 如果 health.ps1 区分 warn/fail 计数：if ($hookIntegrityCheck.level -eq "WARN") { $script:warnCount += 1}
PowerShell# 修改4: D:\Code\health.ps1# 新增 Pipeline 深度健康检查函数；插入 health 检查项区域，并把 $pipelineDeepCheck 加入汇总function Test-Gpt55PipelineDeepHealth { Set-StrictMode -Version 2.0 $ErrorActionPreference = "Continue" $root = $env:CLAUDE_PROJECT_DIR if (-not $root) { $root = $PSScriptRoot } $pipelineDir = Join-Path $root "ai-pipeline" $queueDir = Join-Path $pipelineDir "gpt-queue" $inboxDir = Join-Path $queueDir "inbox" $outboxDir = Join-Path $queueDir "outbox" $failedDir = Join-Path $queueDir "failed" $result = [ordered]@{ name = "gpt55_pipeline_deep" ok = $true level = "OK" queue_dir = $queueDir counts = [ordered]@{ inbox = 0 outbox = 0 failed = 0 } stale_requests = @() browser_launch = $false warnings = @() errors = @() } try { foreach ($dir in @($queueDir, $inboxDir, $outboxDir, $failedDir)) { if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null } } $probePath = Join-Path $queueDir ("health-probe-{0}.tmp" -f ([guid]::NewGuid().ToString("N"))) try { "ok" | Set-Content -LiteralPath $probePath -Encoding UTF8 $probeRead = Get-Content -LiteralPath $probePath -Raw -Encoding UTF8 Remove-Item -LiteralPath $probePath -Force -ErrorAction SilentlyContinue if ($probeRead.Trim() -ne "ok") { $result.level = "FAIL" $result.ok = $false $result.errors += "queue read/write probe mismatch" } } catch { $result.level = "FAIL" $result.ok = $false $result.errors += "queue read/write failed: $($_.Exception.Message)" } $inboxFiles = @(Get-ChildItem -LiteralPath $inboxDir -File -ErrorAction SilentlyContinue) $outboxFiles = @(Get-ChildItem -LiteralPath $outboxDir -File -ErrorAction SilentlyContinue) $failedFiles = @(Get-ChildItem -LiteralPath $failedDir -File -ErrorAction SilentlyContinue) $result.counts.inbox = $inboxFiles.Count $result.counts.outbox = $outboxFiles.Count $result.counts.failed = $failedFiles.Count $cutoff = (Get-Date).AddMinutes(-30) $requestFiles = @($inboxFiles | Where-Object { $_.Name -like "*.request.json" -and $_.LastWriteTime -lt $cutoff }) foreach ($request in $requestFiles) { $responseName = $request.Name -replace "\.request\.json$", ".response.json" $failedName = $request.Name -replace "\.request\.json$", ".failed.json" $responsePath = Join-Path $outboxDir $responseName $failedPath = Join-Path $failedDir $failedName if ( -not (Test-Path -LiteralPath $responsePath) -and -not (Test-Path -LiteralPath $failedPath) ) { $ageMinutes = [math]::Round(((Get-Date) - $request.LastWriteTime).TotalMinutes, 1) $result.stale_requests += [pscustomobject]@{ file = $request.Name path = $request.FullName age_minutes = $ageMinutes expected_response = $responsePath expected_failed = $failedPath } } } if ($result.stale_requests.Count -gt 0 -and $result.level -ne "FAIL") { $result.level = "WARN" $result.warnings += ("stale requests found: {0}" -f $result.stale_requests.Count) } $nodeCode = @"const { chromium } = require('playwright');(async () => { const browser = await chromium.launch({ headless: true }); await browser.close(); console.log('chromium_launch_ok');})().catch(err => { console.error(err && err.stack ? err.stack : String(err)); process.exit(1);});"@ try { Push-Location -LiteralPath $pipelineDir $browserOutput = @(& node -e $nodeCode 2>&1 | ForEach-Object { [string]$_ }) $browserExit = $LASTEXITCODE Pop-Location if ($null -eq $browserExit) { $browserExit = 0 } if ($browserExit -eq 0 -and (($browserOutput -join "`n") -match "chromium_launch_ok")) { $result.browser_launch = $true } else { $result.level = "FAIL" $result.ok = $false $result.errors += ("chromium launch failed: " + ($browserOutput -join "`n")) } } catch { Pop-Location -ErrorAction SilentlyContinue $result.level = "FAIL" $result.ok = $false $result.errors += "chromium launch exception: $($_.Exception.Message)" } Write-Host ("gpt55_pipeline_deep level={0} inbox={1} outbox={2} failed={3} stale={4} browser={5}" -f ` $result.level, $result.counts.inbox, $result.counts.outbox, $result.counts.failed, $result.stale_requests.Count, $result.browser_launch ) return [pscustomobject]$result } catch { $result.level = "FAIL" $result.ok = $false $result.errors += $_.Exception.Message return [pscustomobject]$result }}# 挂载到 health 汇总处：$pipelineDeepCheck = Test-Gpt55PipelineDeepHealth# 如果 health.ps1 使用 $checks 数组：$checks += $pipelineDeepCheck# 如果 health.ps1 区分 warn/fail 计数：if ($pipelineDeepCheck.level -eq "FAIL") { $script:failCount += 1}elseif ($pipelineDeepCheck.level -eq "WARN") { $script:warnCount += 1}
